ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'SMS';
CREATE TYPE "DeliveryStatus" AS ENUM ('PENDING','RETRYING','DELIVERED','BOUNCED','COMPLAINED','FAILED','DEAD_LETTER','SKIPPED');
CREATE TYPE "DigestMode" AS ENUM ('IMMEDIATE','DAILY','WEEKLY','NONE');
ALTER TABLE "Notification" ADD COLUMN "eventType" TEXT NOT NULL DEFAULT 'GENERAL', ADD COLUMN "idempotencyKey" TEXT, ADD COLUMN "metadataJson" TEXT, ADD COLUMN "expiresAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
UPDATE "Notification" SET "idempotencyKey" = "id"; ALTER TABLE "Notification" ALTER COLUMN "idempotencyKey" SET NOT NULL;
CREATE TABLE "NotificationDelivery" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"notificationId" TEXT NOT NULL,"channel" "NotificationType" NOT NULL,"recipient" TEXT,"status" "DeliveryStatus" NOT NULL DEFAULT 'PENDING',"provider" TEXT,"providerMessageId" TEXT,"attemptCount" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMP(3),"lastAttemptAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationDelivery_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationPreference" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"digestMode" "DigestMode" NOT NULL DEFAULT 'IMMEDIATE',"timezone" TEXT NOT NULL DEFAULT 'UTC',"emailEnabled" BOOLEAN NOT NULL DEFAULT true,"inAppEnabled" BOOLEAN NOT NULL DEFAULT true,"pushEnabled" BOOLEAN NOT NULL DEFAULT false,"smsEnabled" BOOLEAN NOT NULL DEFAULT false,"quietHoursStart" TEXT,"quietHoursEnd" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationEventPreference" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"preferenceId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"email" BOOLEAN,"inApp" BOOLEAN,"push" BOOLEAN,"sms" BOOLEAN,CONSTRAINT "NotificationEventPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationTemplate" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"locale" TEXT NOT NULL DEFAULT 'mn',"subjectTemplate" TEXT NOT NULL,"htmlTemplate" TEXT NOT NULL,"textTemplate" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationTemplate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationBranding" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"organizationName" TEXT NOT NULL,"logoUrl" TEXT,"primaryColor" TEXT NOT NULL DEFAULT '#4F46E5',"supportEmail" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationBranding_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PushSubscription" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"endpoint" TEXT NOT NULL,"p256dh" TEXT NOT NULL,"auth" TEXT NOT NULL,"userAgent" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PushSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationRecipient" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"firstName" TEXT,"locale" TEXT NOT NULL DEFAULT 'mn',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationRecipient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DeadLetter" ("id" TEXT NOT NULL,"organizationId" TEXT,"eventType" TEXT NOT NULL,"idempotencyKey" TEXT,"payloadJson" TEXT NOT NULL,"error" TEXT NOT NULL,"attempts" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"replayedAt" TIMESTAMP(3),CONSTRAINT "DeadLetter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProviderEvent" ("id" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerEventId" TEXT NOT NULL,"providerMessageId" TEXT,"type" TEXT NOT NULL,"payloadJson" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProviderEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Notification_organizationId_idempotencyKey_key" ON "Notification"("organizationId","idempotencyKey"); CREATE INDEX "Notification_organizationId_userId_isRead_createdAt_idx" ON "Notification"("organizationId","userId","isRead","createdAt");
CREATE UNIQUE INDEX "NotificationDelivery_notificationId_channel_key" ON "NotificationDelivery"("notificationId","channel"); CREATE INDEX "NotificationDelivery_status_nextAttemptAt_idx" ON "NotificationDelivery"("status","nextAttemptAt"); CREATE INDEX "NotificationDelivery_organizationId_providerMessageId_idx" ON "NotificationDelivery"("organizationId","providerMessageId");
CREATE UNIQUE INDEX "NotificationPreference_organizationId_userId_key" ON "NotificationPreference"("organizationId","userId"); CREATE UNIQUE INDEX "NotificationEventPreference_organizationId_preferenceId_eventType_key" ON "NotificationEventPreference"("organizationId","preferenceId","eventType");
CREATE UNIQUE INDEX "NotificationTemplate_organizationId_eventType_locale_key" ON "NotificationTemplate"("organizationId","eventType","locale"); CREATE UNIQUE INDEX "NotificationBranding_organizationId_key" ON "NotificationBranding"("organizationId");
CREATE UNIQUE INDEX "PushSubscription_organizationId_userId_endpoint_key" ON "PushSubscription"("organizationId","userId","endpoint"); CREATE INDEX "PushSubscription_organizationId_userId_idx" ON "PushSubscription"("organizationId","userId");
CREATE UNIQUE INDEX "NotificationRecipient_organizationId_userId_key" ON "NotificationRecipient"("organizationId","userId"); CREATE INDEX "DeadLetter_createdAt_idx" ON "DeadLetter"("createdAt"); CREATE UNIQUE INDEX "ProviderEvent_provider_providerEventId_key" ON "ProviderEvent"("provider","providerEventId");
ALTER TABLE "NotificationDelivery" ADD CONSTRAINT "NotificationDelivery_notificationId_fkey" FOREIGN KEY ("notificationId") REFERENCES "Notification"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "NotificationEventPreference" ADD CONSTRAINT "NotificationEventPreference_preferenceId_fkey" FOREIGN KEY ("preferenceId") REFERENCES "NotificationPreference"("id") ON DELETE CASCADE ON UPDATE CASCADE;
